// https://emojibase.dev version 17.0.0

const b4a = require('b4a')
const { hostToLE32 } = require('convert-endianness')

const INDEX = b4a.from('', 'base64')

exports.EMOJI_COUNT = 1949
exports.SKIN_COUNT = 475
exports.GROUP_COUNT = 10

exports.EMOJI_RECORDS = to32(0, 54572)
exports.SKIN_RECORDS = to32(54572, 60272)
exports.SHORTCODES = to32(60272, 73132)
exports.EMOTICONS = to32(73132, 73388)
exports.GROUPS = to32(73388, 73468)
exports.POINTS = to32(73468, 100716)
exports.STRINGS = INDEX.subarray(100716, 164336)

function to32 (offset, end) {
  const arr = new Uint32Array(INDEX.buffer, offset, (end - offset) / 4)
  hostToLE32(arr)
  return arr
}
